import os,json,System,Rhino
hub_root='C:\\Users\\08432.SINOLTD\\00.DEVE\\31.AEC\\RHINO_Deve\\EnvironmentalSimulationHub'
path=os.path.join(hub_root,'artifacts','releases','0.3.0','EnvironmentalHub.Plugin.rhp')
loaded=Rhino.PlugIns.PlugIn.LoadPlugIn(path)
plugin_id=System.Guid('bc5a6bd7-4e8f-4f14-a173-ed39f8bf357f')
instance=Rhino.PlugIns.PlugIn.Find(plugin_id)
if instance is None:raise RuntimeError('Plugin failed to load: '+str(loaded))
actual=instance.GetType().Assembly.Location
version=str(instance.GetType().Assembly.GetName().Version)
registered=Rhino.PlugIns.PlugIn.PathFromId(plugin_id)
if os.path.normcase(os.path.normpath(actual))!=os.path.normcase(os.path.normpath(path)):raise RuntimeError('Old plugin is loaded: '+actual)
if version!='0.3.0.0':raise RuntimeError('Unexpected version '+version)
if os.path.normcase(os.path.normpath(registered))!=os.path.normcase(os.path.normpath(path)):raise RuntimeError('Registration still points to '+registered)
Rhino.RhinoApp.RunScript('_EnvironmentalHub',False)
panel_id=System.Guid('c62382ce-7709-4fcd-9dfb-447d1d8a08c0')
panel=Rhino.UI.Panels.GetPanel(panel_id)
if panel is None or panel.ProductVersion!='0.3.0' or panel.GetType().Assembly.Location!=actual:raise RuntimeError('Dock panel is not the new version')
doc=Rhino.RhinoDoc.ActiveDoc
scale=Rhino.RhinoMath.UnitScale(Rhino.UnitSystem.Meters,doc.ModelUnitSystem)
surface=Rhino.Geometry.PlaneSurface(Rhino.Geometry.Plane.WorldXY,Rhino.Geometry.Interval(0,4*scale),Rhino.Geometry.Interval(0,4*scale))
input_id=doc.Objects.AddBrep(surface.ToBrep())
receipt=json.load(open(os.path.join(hub_root,'samples','radiation_smoke','runtime_result.json'),encoding='utf-8'))
request={'GeometryIds':[str(input_id)],'WeatherFile':receipt['weather'],'OutputDirectory':os.path.join(hub_root,'samples','release_030_validation'),'GridMetres':1,'AcceptWarnings':True}
result=json.loads(panel.ExecuteJson(json.dumps(request)))
if abs(result['Statistics']['Mean']-1233.3471168086037)>1e-9:raise RuntimeError('Release solver mismatch')
if panel.RenderedObjectCount!=1:raise RuntimeError('Dock preview missing')
Rhino.RhinoApp.RunScript('_Zoom _Extents',False)
report={'version':version,'display_version':panel.ProductVersion,'plugin_load':str(loaded),'loaded_path':actual,'registered_path':registered,'panel_assembly_path':panel.GetType().Assembly.Location,'dock_panel_visible':Rhino.UI.Panels.IsPanelVisible(panel_id),'mean_kwh_per_m2':result['Statistics']['Mean'],'owned_preview_count':panel.RenderedObjectCount,'status':panel.StatusText,'slot':'armadillo','visual_qa':'Not claimed; native docking and execution verified'}
json.dump(report,open(os.path.join(hub_root,'docs','evidence','release_030_loaded.json'),'w',encoding='utf-8'),indent=2)
print(json.dumps(report))
